import re, json
from pathlib import Path
root = Path("runs/full-01")
bad, total = [], 0
for md in [root / "report.md"] + sorted((root / "tasks").glob("*.md")):
    for text, href in re.findall(r"\[([^\]]+)\]\(([^)]+)\)", md.read_text(encoding="utf-8")):
        total += 1
        target = (md.parent / href).resolve()
        if not target.exists():
            bad.append((md.name, text, href))
print(f"markdown links checked: {total}   broken: {len(bad)}")
for b in bad: print("  BROKEN", b)

j = json.loads((root / "report.json").read_text(encoding="utf-8"))
jbad, jtotal = [], 0
for task, ev in j["evidence"].items():
    for arm, trials in ev["trials"].items():
        for t in trials:
            for key in ("patch", "transcript"):
                jtotal += 1
                if not (root / t[key]).exists(): jbad.append(t[key])
            for gid, g in t["graders"].items():
                jtotal += 1
                if not (root / g["log"]).exists(): jbad.append(g["log"])
print(f"report.json evidence paths checked: {jtotal}   broken: {len(jbad)}")
for b in jbad[:5]: print("  BROKEN", b)
print("\nrecommendation recomputable from report.json:", j["rule"]["fired"], "|", j["rule"]["inputs"])
